SELECT
    source_row.*,
    'f28dbae4-0e66-47ca-8b8e-b4b04b1fcec6',
    'UPDATE',
    'BEFORE'
FROM JISJDW.CHARGE source_row
WHERE CHARGE_ID = '1225705'
;

